def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    high_supply = supply >= 22
    low_supply = supply <= 17

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.6
        avg_prev = DAILY_SALARY * 0.5

    pressure = avg_prev
    if low_supply:
        pressure += 18.0
    elif high_supply:
        pressure -= 10.0

    pressure += urgent_opp * 6.0
    pressure += rich_opp * 2.0

    if hp <= 2 or no_water >= 2:
        bid = max(pressure + 12.0, highest_prev + 3.0, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water >= 1:
        bid = max(pressure + 5.0, avg_prev + 2.0, DAILY_SALARY * 0.72)
    else:
        if high_supply:
            bid = max(18.0, avg_prev - 12.0)
        elif low_supply:
            bid = max(DAILY_SALARY * 0.62, highest_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.48, avg_prev - 2.0)

    if day >= 8:
        bid += 4.0
    if hp >= 8 and no_water == 0 and high_supply:
        bid -= 4.0

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # If alone, bid conservatively
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    lowest_prev_bid = min(yesterday_bids) if yesterday_bids else 0.0

    # Identify if a specific opponent is under pressure (critical HP yesterday)
    critical_pressure = False
    for oid, o in alive_opps:
        hp = o.get('hp', 10)
        if hp is not None and float(hp) <= 3:
            critical_pressure = True
            break

    # Base bid target: aim around the low/medium band unless someone was very aggressive
    # Supply factor: with higher supply, we can bid less.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0  # 20
    if supply >= supply_mid:
        supply_factor = 0.85
    else:
        supply_factor = 1.05

    # If someone yesterday bid extremely high, likely they were trying to lock water.
    # We counter only enough to beat the low end, not the extreme.
    extreme_threshold = DAILY_SALARY * 2.0  # 180

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If my HP is low, prioritize survival with a higher bid.
    if my_hp <= 2.0:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 3.0:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # Adjust based on yesterday's bid distribution
    if highest_prev_bid >= extreme_threshold:
        # Avoid chasing the extreme; bid just above the low end or moderate target.
        if yesterday_bids:
            target = max(base * supply_factor, lowest_prev_bid + 5.0)
        else:
            target = base * supply_factor
    else:
        # Typical day: bid around base, but if critical pressure exists, nudge upward.
        target = base * supply_factor
        if critical_pressure:
            target = max(target, DAILY_SALARY * 0.65)
        # If lowest bid was very low, slightly outbid it to secure water.
        if yesterday_bids and lowest_prev_bid > 0:
            target = max(target, lowest_prev_bid + 2.5)

    # Ensure we don't bid more than we can afford
    bid = min(my_budget, target)

    # If budget is tiny, still bid something proportional to avoid zeroing out.
    if bid <= 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_HP = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        if my_status['hp'] < MAX_HP:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.45

    my_calculated_bid = base_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                my_calculated_bid = DAILY_SALARY * 0.3
            else:
                my_calculated_bid = DAILY_SALARY * 0.95
        else:
            my_calculated_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

            if my_status['hp'] <= 2:
                my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.95)
            elif my_status['hp'] == 3:
                my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.8)
            elif my_status['hp'] <= 5:
                my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.65)

            my_calculated_bid = min(my_calculated_bid, DAILY_SALARY * 0.98)

    current_supply = day_context['supply']
    max_full_water_recipients = int(current_supply // WATER_REQ)

    if max_full_water_recipients < num_alive_opponents + 1:
        if my_status['hp'] <= 5:
            my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.85)
        elif my_status['hp'] <= 7:
            my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.7)

    if max_full_water_recipients == 0 and current_supply > 0:
        if my_status['hp'] <= 5:
            my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.9)
        elif my_status['hp'] <= 7:
            my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], my_calculated_bid)
    return max(1.0, final_bid)
